{"id":1,"name":"Oauth - RFC","script":"(function bearerToken() {
    function evaluateBearerToken() {

        let authorization = String($request.getHeader("Authorization"));
        $console.debug("authorization", authorization);
        if(authorization !== null && authorization !== undefined) {
            let authorizationParts = authorization.split(" ");
            $console.debug("authorizationParts", authorizationParts);
            if(authorizationParts.length === 2) {
                let tokenType = String(authorizationParts[0]);
                let tokenValue = String(authorizationParts[1]);
                let tokenDecoded = String($base64.decodeString(tokenValue));
                $console.debug("tokenType", tokenType);
                $console.debug("tokenValue", tokenValue);
                $console.debug("tokenDecoded", tokenDecoded);
                if(String(tokenType.toUpperCase()) === "BEARER") {
                    let tokenParts = tokenDecoded.split(":");
                    if(tokenParts.length === 2) {
                        let auth = {};
                        auth.value = String(authorization);
                        auth.type = String(tokenType);
                        auth.token = String(tokenValue);
                        auth.client_id = String(tokenParts[0]);
                        auth.access_token = String(tokenParts[1]);
                        $console.debug("auth", auth);
                        return auth;
                    }
                }
            }
        }
        return null;
    }

    function generateErrorMessage(strStatus, strResult, strMensagem) {
        var jsonError = {};
        jsonError.result = strResult; //"API Error";
        jsonError.status = strStatus; //"ERROR";
        jsonError.details = strMensagem;
        $call.response = new com.sensedia.interceptor.externaljar.dto.ApiResponse();
        $call.response.setStatus(strStatus);
        $call.response.getBody().setString(JSON.stringify(jsonError), "utf-8");
        $call.response.setHeader("Content-type", "application/json");

    }

    try {
        let authorization = evaluateBearerToken();
        if (authorization !== undefined && authorization !== null) {
            $request.setHeader("client_id", authorization.client_id);
            $request.setHeader("access_token", authorization.access_token);
        }

        else {   
            generateErrorMessage(404, "Invalid Token", "Invalid Token");
            $call.stopFlow = true;
            $call.decision.setAccept(false);
        }
    } catch (exception) {
        $call.tracer.trace("Exception message => " + exception.message + " <= in line => " + exception.stack);
        $console.debug(">sensedia => Exception", exception);

        throw exception;
    }
})();","abort":false,"debug":false,"visibility":{"id":18,"visibilityType":"ORGANIZATION","owner":"jansen.carvalho","users":[]},"tags":["Oauth"],"ignoreBodyValidationMultiPartFormData":false}
